function guardProof(node, templateTextNodes = new Set(), undefinedNodes = new Set()) {
    // Only nodes generated by Vue for a complete text interpolation are marked.
    // A + inside _s(amount + '1') is a user expression and is never marked.
    if (templateTextNodes.has(node)) return 'vue_text_concatenation'
    if ((node.type === 'BinaryExpression' || node.type === 'UnaryExpression')
        && literalIntegerValue(node) !== null) return 'literal_integer_arithmetic'
    if (node.type !== 'BinaryExpression' || !['===','!==','==','!='].includes(node.operator)) return null
    for (const operand of [node.left, node.right]) {
        if (['===','!=='].includes(node.operator) && operand.type === 'StringLiteral' && operand.value === '') return 'strict_empty_string_guard'
        if (['===','!=='].includes(node.operator) && operand.type === 'StringLiteral' && operand.value.trim() !== '' && !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(operand.value.trim())) return 'nonnumeric_string_equality'
        // Abstract equality against nonnumeric text cannot compare numeric amounts:
        // string/number coercion yields NaN. Hex, Infinity and whitespace are excluded.
        if (['==','!='].includes(node.operator) && operand.type === 'StringLiteral'
            && operand.value.trim() !== '' && Number.isNaN(Number(operand.value))) return 'loose_nonnumeric_string_equality'
        if (['===','!=='].includes(node.operator) && ['NullLiteral','BooleanLiteral'].includes(operand.type)) return 'strict_type_guard'
        // JavaScript abstract equality with literal null checks presence, without
        // converting the other operand to a numeric amount. Nested operands remain audited.
        if (['==','!='].includes(node.operator) && operand.type === 'NullLiteral') return 'nullish_presence_guard'
    }
    if (['===','!=='].includes(node.operator)) {
        for (const operand of [node.left,node.right]) {
            if (operand.type==='Identifier' && operand.name==='undefined' && undefinedNodes.has(operand)) return 'strict_undefined_guard'
            if (operand.type==='UnaryExpression' && operand.operator==='void' && operand.argument.type==='NumericLiteral' && operand.argument.value===0) return 'strict_undefined_guard'
        }
    }
    return null
}

/** Prove every intermediate with BigInt; never coerce a string or a dynamic operand. */
function literalIntegerValue(node) {
    let value
    const raw = node.extra?.raw
    if (node.type === 'NumericLiteral' && typeof raw === 'string' && raw.length <= 16
        && /^(?:0|[1-9][0-9]*)$/.test(raw) && Number.isSafeInteger(node.value)
        && !Object.is(node.value, -0)) {
        value = BigInt(raw)
        if (BigInt(node.value) !== value) return null // Reject a rounded token from the parser.
    } else if (node.type === 'UnaryExpression' && ['+','-'].includes(node.operator)) {
        const operand = literalIntegerValue(node.argument)
        if (operand === null || (node.operator === '-' && operand === 0n)) return null
        value = node.operator === '-' ? -operand : operand
    } else if (node.type === 'BinaryExpression') {
        const a = literalIntegerValue(node.left), b = literalIntegerValue(node.right)
        if (a === null || b === null) return null
        if (node.operator === '+') value = a + b
        else if (node.operator === '-') value = a - b
        else if (node.operator === '*') {
            value = a * b
            if (value === 0n && (a < 0n || b < 0n)) return null // Preserve JS negative-zero semantics.
        } else if (node.operator === '/') {
            if (b === 0n || a % b !== 0n || (a === 0n && b < 0n)) return null
            value = a / b
        } else if (node.operator === '%') {
            if (b === 0n) return null
            value = a % b
            if (value === 0n && a < 0n) return null
        } else return null
    } else return null
    return value >= -9007199254740991n && value <= 9007199254740991n ? value : null
}

/** The compiler joins literal text and already stringified interpolations. */
function vueTextConcatenations(root) {
    const nodes = new Set()
    function isText(node) {
        if (node.type === 'StringLiteral') return true
        if (node.type === 'CallExpression' && node.callee.type === 'Identifier'
            && node.callee.name === '_s' && node.arguments.length === 1
            && node.arguments[0].type !== 'SpreadElement') return true
        return node.type === 'BinaryExpression' && node.operator === '+'
            && isText(node.left) && isText(node.right)
    }
    function mark(node) {
        if (node.type !== 'BinaryExpression') return
        nodes.add(node)
        mark(node.left)
        mark(node.right)
    }
    if (isText(root)) mark(root)
    return nodes
}

function globalUndefinedIdentifiers(ast, template=false) {
    const nodes=new Set()
    const traverse=require('@babel/traverse').default
    if (template) return nodes
    const file=ast.type === 'File' ? ast : ast.type === 'Program' ? {type:'File',program:ast} : {type:'File',program:{type:'Program',sourceType:'script',body:[{type:'ExpressionStatement',expression:ast}]}}
    let dynamic=false
    traverse(file, {WithStatement() {dynamic=true}, CallExpression(path) {if(path.node.callee.type==='Identifier' && path.node.callee.name==='eval') dynamic=true}})
    if (dynamic) return nodes
    traverse(file, {ReferencedIdentifier(path) {
        if (path.node.name==='undefined' && !path.scope.getBinding('undefined')) nodes.add(path.node)
    }})
    return nodes
}

module.exports = guardProof
module.exports.vueTextConcatenations = vueTextConcatenations
module.exports.globalUndefinedIdentifiers = globalUndefinedIdentifiers
